export function historicalDraft(example,step=20){
 const d={step,set:example.game,blue:example.blue.id,red:example.red.id,bans:{blue:[],red:[]},picks:{blue:[],red:[]},used:[],patch:example.patch,history:[],reference:true};
 for(const a of example.actions.slice(0,step)){d.history.push(a);if(a.kind==='ban')d.bans[a.side].push(a.champion);else d.picks[a.side].push({...a,team:a.team});}
 return d;
}
function pickCard(c,d,side,r,index,reference){
 const {E,state:s,esc}=c,id=d[side],picks=d.picks[side],pick=reference?picks.find(p=>p.role===r):picks[index];
 const assignedRole=pick?.role,player=reference?reference[side].lineup.find(p=>p.role===r):assignedRole?E.getPlayer(s,s.teams[id].lineup[assignedRole]):null;
 const turn=d.reference?null:E.draftTurn(d),pending=!pick&&turn?.side===side&&turn?.kind==='pick'&&picks.length===index;
 const champion=pick?E.database().champMap[pick.champion]:null,order=pick?picks.indexOf(pick)+1:index+1;
 return `<div class="broadcast-pick ${pick?'locked':''} ${pending?'selecting':''}" data-side="${side}" data-slot="${side[0].toUpperCase()}${order}">${pick?`<img class="loading-portrait" src="./assets/champions-loading/${pick.champion}.jpg" alt="${esc(champion.name)}" loading="eager">`:`<div class="broadcast-placeholder"><strong>${side==='blue'?'B':'R'}${index+1}</strong><span>${pending?'선택 중':'대기'}</span></div>`}<span class="broadcast-order">${side==='blue'?'B':'R'}${order}</span><div class="broadcast-nameplate">${champion?`<strong>${esc(champion.name)}</strong>`:''}<span>${esc(player?.name??player?.player??'선수 미배정')}</span><small>${assignedRole??'포지션 미배정'}</small></div></div>`;
}
export function broadcastStrip(c,d,m,reference=null){
 const {E,state:s,esc,img,teamName,teamIcon}=c;
 const bans=side=>`<div class="broadcast-bans ${side}"><span>${side==='blue'?'BLUE':'RED'} BANS</span>${Array.from({length:5},(_,i)=>`<div class="broadcast-ban ${d.bans[side][i]?'banned':''}" title="${d.bans[side][i]?esc(E.database().champMap[d.bans[side][i]].name):'밴 대기'}">${d.bans[side][i]?img(d.bans[side][i]):'<b>—</b>'}${i===2?'<i class="ban-phase-divider"></i>':''}</div>`).join('')}</div>`;
 return `<section class="broadcast-strip" aria-label="양 팀 밴픽 현황">${d.used.length?`<div class="broadcast-series"><span>SERIES BAN <b>${d.used.length}</b></span><div class="series-used-icons">${d.used.map(id=>`<span>${img(id)}</span>`).join('')}</div><small>이전 세트 양 팀 픽 · 재선택 불가</small></div>`:''}<div class="broadcast-bans-row">${bans('blue')}<span class="broadcast-set-label">GAME ${d.set} · ${reference?(reference.year===2022?'STANDARD DRAFT':'FEARLESS DRAFT'):'FEARLESS DRAFT'}</span>${bans('red')}</div><div class="broadcast-rosters"><div class="broadcast-team blue">${E.ROLES.map((r,i)=>pickCard(c,d,'blue',r,i,reference)).join('')}</div><div class="broadcast-center"><div class="broadcast-league">LCK<span>MANAGER</span></div><div class="broadcast-team-logos">${teamIcon(d.blue)}${teamIcon(d.red)}</div><strong>${reference?reference.seriesScoreBefore.blue:m.score[m.teams.indexOf(d.blue)]} <i>:</i> ${reference?reference.seriesScoreBefore.red:m.score[m.teams.indexOf(d.red)]}</strong><small>BO${m.bestOf} · GAME ${d.set}</small><small>PATCH ${esc(E.patchLabel(d.patch))}</small></div><div class="broadcast-team red">${E.ROLES.map((r,i)=>pickCard(c,d,'red',r,i,reference)).join('')}</div></div></section>`;
}
function compositionMarkup(c,d){
 const {E,state:s,esc}=c;if(!E.assignmentsReady(d))return '<p class="composition-pending">다섯 포지션을 모두 배치하면 조합과 시간대별 상성을 분석합니다.</p>';
 const report=E.draftComposition(d),ours=d.blue===s.myTeam?'blue':'red',enemy=ours==='blue'?'red':'blue';
 const chance=p=>Math.round((ours==='blue'?p:1-p)*100);
 return `<section class="composition-report" aria-label="챔피언 조합 분석"><header><strong>챔피언 조합 분석</strong><span>조합만 비교한 한타 예상 · 20분 ${chance(report.blueChance20)}% · 45분 ${chance(report.blueChance45)}%</span></header><p class="small muted">동일 전력·골드·버프를 가정한 우리 팀의 조합 상성입니다. 현재 전과는 0/0/0으로 가정합니다. 실제 교전에는 참가 포지션·선수·골드와 챔피언별 킬·데스·어시스트가 추가됩니다.</p><div class="combat-scenarios">${report.scenarios.map(x=>`<article><span>${esc(x.label)} · ${x.minute}분</span><strong>${chance(x.blueChance)}%</strong></article>`).join('')}</div><div>${[ours,enemy].map((side,i)=>`<article><strong>${i?'상대':'우리'} · ${esc(s.teams[d[side]].abbr)}</strong><span>${report[side+'Labels'].map(esc).join(' · ')}</span></article>`).join('')}</div></section>`;
}
function assignmentMarkup(c,d){
 const {E,state:s,esc,img,btn}=c,side=d.blue===s.myTeam?'blue':'red',picks=d.picks[side],clock=d.assignment;
 return `<section class="assignment-room" aria-label="밴픽 후 포지션 배치"><div class="assignment-heading"><div><h2>포지션 · 선수 배치</h2><p>선택한 다섯 챔피언을 선수에게 배정하세요. 모든 챔피언을 모든 포지션에 배치할 수 있습니다.</p></div><div class="assignment-clock ${clock.expired?'expired':''}" role="timer" aria-label="배치 남은 시간"><strong id="assignment-seconds">${Math.ceil(clock.remaining)}</strong><span>${clock.expired?'자동 배치 완료':clock.paused?'시간 정지':'SECONDS'}</span></div></div><div class="assignment-champions">${picks.map(p=>`<div class="assignment-token ${p.role?'assigned':''}" draggable="true" data-drag-champion="${p.champion}" title="포지션 칸으로 끌어 놓거나 아래 선택 상자를 사용하세요">${img(p.champion)}<strong>${esc(E.database().champMap[p.champion].name)}</strong><small>${p.role??'미배정'}</small></div>`).join('')}</div><div class="assignment-roles">${E.ROLES.map(r=>{const pick=picks.find(p=>p.role===r),player=E.getPlayer(s,s.teams[d[side]].lineup[r]);return `<div class="assignment-role ${pick?'filled':''}" data-drop-role="${r}" data-side="${side}"><span class="role-chip">${r}</span>${pick?img(pick.champion):'<div class="assignment-empty">?</div>'}<div><strong>${esc(player?.name??r)}</strong><span>${E.ROLE_NAMES[r]}</span></div><select data-change="assign-champion" data-side="${side}" data-role="${r}" aria-label="${r} 챔피언 배치"><option value="">챔피언을 선택하세요</option>${picks.map(p=>`<option value="${p.champion}" ${pick?.champion===p.champion?'selected':''}>${esc(E.database().champMap[p.champion].name)}${p.role&&p.role!==r?' · '+p.role:''}</option>`).join('')}</select></div>`;}).join('')}</div>${compositionMarkup(c,d)}<div class="assignment-tools">${btn('코치 추천으로 전체 배치','assignment-auto','','primary')}${btn(clock.paused?'타이머 재개':'시간 정지','assignment-pause','','ghost')}<span>시간 종료 시 미배정 칸만 자동 완성합니다. 직접 확정하면 경기가 시작됩니다.</span></div></section>`;
}
export function draftMarkup(c){
 const {E,state:s,ui,data,esc,btn,badge,img,teamName,teamIcon}=c;
 const reference=ui.draftReferenceId?data.draftExamples.examples.find(e=>e.id===ui.draftReferenceId):null;
 const d=reference?historicalDraft(reference,ui.referenceStep??20):s.activeDraft;
 if(!d)return '<div class="empty">진행 중인 밴픽이 없습니다.</div>';
 const m=reference?{teams:[d.blue,d.red],bestOf:5,competition:reference.league}:s.matches.find(m=>m.id===d.matchId);
 const turn=reference?(reference.actions[d.step]??null):E.draftTurn(d),legal=new Set(reference?[]:E.legalChampions(s,d).map(c=>c.id)),human=turn?.team===s.myTeam&&!reference;
 const hover=ui.hoverChampion&&legal.has(ui.hoverChampion)?ui.hoverChampion:null;
 const preview=hover??d.history.at(-1)?.champion??(reference?reference.actions[0].champion:null);
 const champion=E.database().champMap[preview];
 const pool=data.champions.filter(c=>c.available[d.patch]&&(ui.draftRole==='all'||c.roles.includes(ui.draftRole))&&(c.name+c.id).toLowerCase().includes(ui.draftSearch.toLowerCase()));
 const currentKind=turn?.kind==='ban'?'밴':'픽',status=E.draftStatus(d);
 const orderName=status.order==='first'?'선픽 팀':'후픽 팀';
 const blockLabel=turn?.kind==='pick'?`${orderName} · ${status.count}픽 중 ${status.index}번째`:`${orderName} · ${Math.max(0,(d.bans[turn?.side]?.length??0)-(d.step>=12?3:0))+1}/${d.step>=12?2:3}밴`;
 const roundBar=reference?'':`<div class="draft-rounds" aria-label="2026 LCK 밴픽 순서">${E.DRAFT_ROUNDS.map(r=>`<div class="${status.id===r.id?'active':''}" ${status.id===r.id?'aria-current="step"':''}><strong>${r.label}</strong><span>${r.summary}</span></div>`).join('')}</div>`;
 const phase=d.step===20?'포지션 배치 시간':d.step<6?'1차 밴':d.step<12?'1차 픽':d.step<16?'2차 밴':'2차 픽';
 const phaseSteps=E.draftActions(d).map(([side,kind],i)=>`<span class="draft-step ${side} ${i<d.step?'done':''} ${i===d.step?'current':''}" title="${i+1}. ${side} ${kind}">${kind==='ban'?'×':'●'}</span>`).join('');
 return `<div class="broadcast-draft ${reference?'reference-draft':d.step<20?'expanded-pool':''}"><header class="broadcast-header"><div class="broadcast-heading blue">${teamIcon(d.blue)}<div><strong>${teamName(d.blue)}</strong><small>BLUE SIDE ${!reference?`· ${d.firstPickSide==='red'?'후픽':'선픽'}`:''} ${d.blue===s.myTeam&&!reference?'· MY TEAM':''}</small></div></div><div class="broadcast-header-middle"><h1>${reference?'실제 경기 밴픽 다시보기':d.step===20?'포지션 배치':'챔피언 선택'}</h1><span>${reference?esc(reference.title):`${esc(m.competition)} · ${d.set}세트 · ${phase}`}</span></div><div class="broadcast-heading red"><div><strong>${teamName(d.red)}</strong><small>RED SIDE ${!reference?`· ${d.firstPickSide==='red'?'선픽':'후픽'}`:''} ${d.red===s.myTeam&&!reference?'· MY TEAM':''}</small></div>${teamIcon(d.red)}</div></header><div class="draft-progress-bar">${phaseSteps}<strong>${d.step} / 20</strong></div>${roundBar}<div class="broadcast-stage ${!reference&&d.step===20?'assignment-stage':''}"><div class="draft-control-room">${!reference&&d.step===20?assignmentMarkup(c,d):reference?`<div class="reference-meta">${badge('실제 기록','gold')} ${reference.date} · PATCH ${reference.sourcePatch}<p>${reference.year===2022?'당시에는 일반 드래프트였습니다. 이 재생은 커리어의 피어리스 규칙이나 결과를 변경하지 않습니다.':'실제 대회 기록을 재생합니다. 커리어 선수단과 독립된 참고 화면입니다.'}</p></div><div class="reference-actions">${reference.actions.map((a,i)=>`<button class="reference-action ${a.side} ${i<d.step?'revealed':''} ${i===d.step-1?'current':''}" data-action="reference-jump" data-index="${i+1}"><span>${String(i+1).padStart(2,'0')}</span>${img(a.champion)}<div><strong>${a.side==='blue'?'B':'R'} · ${a.kind==='ban'?'BAN':a.slotLabel}</strong><span>${esc(a.name)}</span></div><small>${esc(a.player??'')}</small></button>`).join('')}</div>`:`<div class="draft-turn ${turn?.side??'complete'}"><strong>${d.step===20?'라인업을 확인하세요':`${human?'우리 팀':'상대 팀'} ${currentKind} 선택`}</strong>${turn?`<em class="draft-block-count">${blockLabel}</em>`:''}<span>${ui.draftBusy?'상대가 선택을 확정하고 있습니다.':d.step===20?'역할 교환 후 경기를 시작할 수 있습니다.':turn?.kind==='ban'?'챔피언 선택 후 밴 확정을 누르세요.':'챔피언 선택 후 픽 확정을 누르세요.'}</span><b>${d.step===20?'READY':ui.draftBusy?'LOCKING':'SELECT'}</b></div><div class="draft-pool"><div class="filterbar"><input id="draft-search" type="search" value="${esc(ui.draftSearch)}" placeholder="챔피언 검색" aria-label="밴픽 챔피언 검색"><div class="filters">${['all',...E.ROLES].map(r=>`<button class="filter ${ui.draftRole===r?'active':''}" data-action="draft-role" data-id="${r}">${r==='all'?'전체':r}</button>`).join('')}</div></div><div class="champ-grid">${pool.map(ch=>{const excluded=E.draftUnavailableReason(s,d,ch.id);return `<button class="champ-card ${legal.has(ch.id)?'':'unavailable'} ${hover===ch.id?'hovered':''}" data-action="draft-pick" data-id="${ch.id}" ${!human||!legal.has(ch.id)||ui.draftBusy?'disabled':''} title="${esc(excluded||ch.name)}">${img(ch.id)}<strong>${esc(ch.name)}</strong>${excluded?`<small>${excluded}</small>`:''}</button>`;}).join('')}</div></div>`}</div><aside class="champion-spotlight ${hover?'has-hover':''}">${champion?`<img src="./assets/champions-loading/${champion.id}.jpg" alt="${esc(champion.name)} 로딩 초상화" class="spotlight-art"><div class="spotlight-caption"><small>${reference?'HISTORICAL DRAFT':hover?'선택 미리보기':d.history.length?'최근 확정':'챔피언 선택'}</small><strong>${esc(champion.name)}</strong><span>${esc(champion.title)}</span></div>`:'<div class="spotlight-caption"><strong>CHAMPION SELECT</strong></div>'}<div class="draft-lock-controls">${reference?`${btn('처음','reference-first','','compact')}${btn('이전','reference-prev','','compact')}${btn('다음 선택','reference-next','','primary')}${btn('전체 보기','reference-end','','compact')}`:d.step===20?btn('배치 확정 · 경기 시작','commit-draft',E.assignmentsReady(d)?'':'disabled','primary'):`${btn(`${currentKind} 확정`,'draft-lock',!human||!hover||ui.draftBusy?'disabled':'','primary')}${btn('이번 선택 자동','draft-auto-one',ui.draftBusy?'disabled':'')}${btn('남은 밴픽 자동','draft-auto-rest',ui.draftBusy?'disabled':'','ghost')}`}</div></aside></div>${broadcastStrip(c,d,m,reference)}<footer class="broadcast-footer"><span>${reference?'출처: Oracle’s Elixir 경기별 픽·밴 순서 / 실제 역할 배치':`역할 필터는 목록 보기 설정입니다. 최종 포지션은 밴픽 종료 후 배치합니다. · 피어리스 · 앞 세트 양 팀의 ${d.used.length}종 소진 / 현재 세트 밴은 세트 종료 시 초기화`}</span><div>${btn(reference?'참고 경기 목록':'실제 경기 참고','draft-examples','','compact ghost')}${btn(reference?'커리어로 돌아가기':'경기 준비로','draft-back','','compact ghost')}</div></footer></div>`;
}
